<?php use Namira\StoreCatalog; $meta=$product['meta'];$available=array_filter($product['variants'],fn($v)=>(int)$v['stock']>0||$v['unlimited']); ?>
<link rel="stylesheet" href="/assets/store.css?v=009"><script src="/assets/store.js?v=009" defer></script>
<nav aria-label="مسیر صفحه" class="store-breadcrumb"><a href="<?= e(url('shop')) ?>">فروشگاه</a><?php foreach($product['categories'] as $c): ?> / <a href="<?= e(url('shop',['category'=>$c['id']])) ?>"><?= e($c['title']) ?></a><?php endforeach ?> / <?= e($product['title']) ?></nav>
<?php if($preview): ?><p class="notice">پیش‌نمایش مدیریتی؛ این نشانی مجوز انتشار محصول نیست.</p><?php endif ?>
<section class="store-detail"><div class="store-gallery"><?php if($product['media']): ?><?php foreach($product['media'] as $m): ?><a href="<?= e(url('store-media',['id'=>$m['id']])) ?>" target="_blank" rel="noopener"><img width="800" height="800" loading="lazy" src="<?= e(url('store-media',['id'=>$m['id']])) ?>" alt="<?= e($m['alt']?:$product['title']) ?>"></a><?php endforeach ?><?php elseif($product['image_id']): ?><img src="<?= e(url('media',['id'=>$product['image_id']])) ?>" alt="<?= e($product['title']) ?>"><?php else: ?><div class="store-placeholder">ن</div><?php endif ?></div><div class="store-buy"><p class="muted"><?= e(StoreCatalog::DELIVERY[$product['delivery']]) ?> · <?= e(StoreCatalog::PRODUCTION[$product['production']]) ?></p><h1><?= e($product['title']) ?></h1><?php if($meta['summary']??''): ?><p><?= nl2br(e($meta['summary'])) ?></p><?php endif ?><?php if($product['production']==='custom'): ?><p class="notice">تصویر محصول نمونهٔ قالب است. شخصی‌سازی پس از سفارش، به‌صورت دستی توسط تیم نامیرا انجام می‌شود.</p><?php endif ?><?php if($meta['preparation']??''): ?><p>زمان تقریبی آماده‌سازی: <?= e($meta['preparation']) ?></p><?php endif ?>
<?php if($product['pricing']==='quote'): ?><p class="price">استعلام قیمت</p><p class="notice">ثبت استعلام آنلاین در مرحلهٔ بعدی توسعهٔ فروشگاه فعال خواهد شد؛ پرداخت با مبلغ نامشخص انجام نمی‌شود.</p><?php elseif(!StoreCatalog::checkoutReady($product)): ?><p class="notice">این محصول هنوز برای خرید آنلاین فعال نشده است. فرایند سفارش اختصاصی و تحویل دیجیتال در حال تکمیل است.</p><?php else: ?><form method="post" data-store-buy><?= Namira\Security::field() ?><input type="hidden" name="action" value="cart"><label for="store-variant">گزینهٔ محصول</label><select name="variant_id" id="store-variant" required><?php foreach($product['variants'] as $v): ?><option value="<?= (int)$v['id'] ?>" data-price="<?= (int)($v['sale_price']??$v['price']) ?>" <?= $v['stock']<1?'disabled':'' ?>><?= e($v['attributes']) ?> · <?= fa(number_format((int)($v['sale_price']??$v['price']))) ?> تومان <?= $v['stock']<1?'(ناموجود)':'' ?></option><?php endforeach ?></select><label>تعداد<input type="number" name="quantity" min="1" max="99" value="1" required></label><p class="price" data-store-price aria-live="polite"></p><button class="primary" <?= !$available?'disabled':'' ?>><?= $available?'افزودن به سبد خرید':'ناموجود' ?></button></form><?php endif ?></div></section>
<?php foreach(['description'=>'معرفی محصول','specifications'=>'مشخصات','sales_terms'=>'شرایط فروش و ارسال','digital_rights'=>'حقوق استفادهٔ فایل دیجیتال'] as $key=>$label): $text=$key==='description'?$product['description']:($meta[$key]??'');if(trim($text)==='')continue; ?><section class="panel"><h2><?= $label ?></h2><div class="prose"><?= nl2br(e($text)) ?></div></section><?php endforeach ?>
